"""Export canonical JSON Schema and OpenAPI; never edit generated files manually."""

import json
from pathlib import Path

from src.api.app import create_app
from src.api.routes.health import HealthResponse, ReadinessResponse
from src.domain.models import (
    MigrationPlan,
    PatchProposal,
    Policy,
    PublicationRequest,
    ValidationEvidence,
)

ROOT = Path(__file__).resolve().parents[1]


def main():
    schemas = ROOT / "contracts/json-schema"
    schemas.mkdir(parents=True, exist_ok=True)
    for model in [
        MigrationPlan,
        PatchProposal,
        ValidationEvidence,
        PublicationRequest,
        Policy,
        HealthResponse,
        ReadinessResponse,
    ]:
        (schemas / f"{model.__name__}.json").write_text(
            json.dumps(model.model_json_schema(), indent=2, sort_keys=True) + "\n"
        )
    (ROOT / "contracts/openapi/control.json").write_text(
        json.dumps(create_app().openapi(), indent=2, sort_keys=True) + "\n"
    )
    # The UI currently consumes only health. Generate its contract from the same model.
    schema = HealthResponse.model_json_schema()
    fields = []
    for name, field in schema["properties"].items():
        if "const" not in field:
            raise ValueError(
                "Health type generator supports literal fields only; extend explicitly"
            )
        fields.append(f"  {name}: {json.dumps(field['const'])};")
    (ROOT / "frontend/src/shared/api/generated.ts").write_text(
        "// Generated by scripts/generate_contracts.py. Do not edit.\n"
        + "export interface HealthResponse {\n"
        + "\n".join(fields)
        + "\n}\n"
    )


if __name__ == "__main__":
    main()
